 async function payWithUPI(upiId:string,amountValue:unknown,sellerName:string){
  const receiver=String(upiId||'').trim();
  const amount=Number(amountValue);
  if(!/^[a-zA-Z0-9._-]+@[a-zA-Z0-9.-]+$/.test(receiver)){Alert.alert('Invalid UPI ID','Enter a valid seller UPI ID.');return;}
  if(!Number.isFinite(amount)||amount<=0){Alert.alert('Invalid amount','Enter a valid payment amount.');return;}
  const params=[`pa=${encodeURIComponent(receiver)}`,`pn=${encodeURIComponent(sellerName.trim()||'Seller')}`,`am=${amount.toFixed(2)}`,'cu=INR',`tn=${encodeURIComponent('CampusLoop Purchase')}`];
  const upiUrl='upi://pay?'+params.join('&');
  Alert.alert('Confirm payment',`Pay ₹${amount.toFixed(2)} to ${receiver}?`,[
   {text:'Cancel',style:'cancel'},
   {text:'Continue',onPress:async()=>{
    try{await Linking.openURL(upiUrl);Alert.alert('Payment app opened','Complete the payment in your UPI app. CampusLoop cannot verify payment yet. Ask the seller to confirm receipt; do not treat this as a paid order.');}
    catch{Alert.alert('Payment app error','Unable to open a supported UPI app.');}
   }}
  ]);
 }
 async function request(path:string,method='GET',body?:any,auth=token){
  let res:Response;try{res=await fetch(API_BASE_URL+'/api'+path,{method,headers:{'Content-Type':'application/json',...(auth?{'Authorization':'Bearer '+auth}:{})},...(body?{body:JSON.stringify(body)}:{})});}catch(e){throw Error('Cannot reach Java server. Check config.ts IP, Wi-Fi, and Spring Boot.');}
  const data=await res.json().catch(()=>({}));if(!res.ok)throw Error(data.error||data.message||'Request failed');return data;
 }
 async function load(auth=token){try{const [p,d,n,m,b,saved]=await Promise.all([request('/posts','GET',undefined,auth),request('/deals','GET',undefined,auth),request('/notifications','GET',undefined,auth),request('/my-posts','GET',undefined,auth),request('/blogs','GET',undefined,auth),request('/saved','GET',undefined,auth)]);setPosts(p);setDeals(d);setNotes(n);setMine(m);setBlogs(b);setSavedPosts(saved);}catch(e:any){Alert.alert('Connection',e.message);}}
 async function loadConnections(auth=token){try{setConnections(await request('/users','GET',undefined,auth));}catch(e:any){Alert.alert('Connection',e.message);}}
 async function loadAdminData(){try{const [safety,disputes,reports,tickets,analytics]=await Promise.all([request('/admin/safety-reports'),request('/admin/disputes'),request('/admin/reports'),request('/admin/support-tickets'),request('/admin/analytics')]);setAdminSafetyReports(safety);setAdminDisputes(disputes);setAdminReports(reports);setAdminTickets(tickets);setAdminAnalytics(analytics);}catch(e:any){Alert.alert('Admin',e.message);}}
 async function loadAnnouncements(){try{setAnnouncements(await request('/announcements'));setTab('Announcements');}catch(e:any){Alert.alert('Announcements',e.message);}}
 async function loadLostFound(){try{setLostFound(await request('/lost-found'));setForm(current=>({...current,lostKind:current.lostKind||'Lost'}));setTab('LostFound');}catch(e:any){Alert.alert('Lost and found',e.message);}}
 function openCampusLocation(place:string,coordinates?:{lat:number;lon:number}){const query=coordinates?`${coordinates.lat},${coordinates.lon}`:encodeURIComponent(`Kongu Engineering College, Perundurai, ${place}`);Alert.alert(t('Open in Google Maps?'),`${place} · Kongu Engineering College`,[{text:t('Cancel'),style:'cancel'},{text:t('Open Google Maps'),onPress:()=>{void Linking.openURL(`https://www.google.com/maps/search/?api=1&query=${query}`).catch((error:any)=>Alert.alert(t('Campus Map'),error.message));}}]);}
 async function loadTheme(userId:number){const saved=await AsyncStorage.getItem(`campusloop_dark_${userId}`);setIsDark(saved==='true');}
 async function toggleDarkMode(){const next=!isDark;try{if(me)await AsyncStorage.setItem(`campusloop_dark_${me.id}`,String(next));setIsDark(next);}catch(error:any){Alert.alert(t('Appearance'),error.message);}}
 async function loadSupportTickets(){try{setSupportTickets(await request('/support-tickets'));}catch(e:any){Alert.alert('Support',e.message);}}
 async function showNotifications(){setTab('Notifications');try{await request('/notifications/read','POST');setNotes(await request('/notifications'));}catch(e:any){Alert.alert('Connection',e.message);}}
 async function openNotification(notification:Item){try{if(notification.event_type==='deal'&&notification.event_id){await openDeal(await request(`/deals/${notification.event_id}`));return;}if(notification.event_type==='post'&&notification.event_id){await openPost(await request(`/posts/${notification.event_id}`));return;}if(notification.event_type==='chat'&&notification.event_id){const users=connections.length?connections:await request('/users');setConnections(users);const person=users.find((user:Item)=>Number(user.id)===Number(notification.event_id));if(person){await openChat(person);return;}}if(notification.event_type==='support'){setTab('Settings');await loadSupportTickets();return;}if(notification.event_type==='admin'&&me?.is_admin){setTab('Admin');await loadAdminData();return;}const dealMatch=String(notification.body).match(/deal #(\\d+)/i);if(dealMatch){await openDeal(await request(`/deals/${dealMatch[1]}`));return;}if(me?.is_admin&&/safety report|support request/i.test(String(notification.body))){setTab('Admin');await loadAdminData();return;}Alert.alert(t('Notification'),t('This notification has no linked event.'));}catch(e:any){Alert.alert(t('Notification'),e.message);}}
 async function openChat(person:Item){setChatPerson(person);setDirectMessages([]);setDirectDraft('');setTab('DirectChat');try{setDirectMessages(await request('/users/'+person.id+'/messages'));setConnections(current=>current.map(user=>user.id===person.id?{...user,unread_count:0}:user));}catch(e:any){Alert.alert('Chat',e.message);}}
 async function sendDirectMessage(){if(!directDraft.trim()||!chatPerson)return;await action(async()=>{const result=await request('/users/'+chatPerson.id+'/messages','POST',{body:directDraft});setDirectMessages(await request('/users/'+chatPerson.id+'/messages'));setDirectDraft('');return result;});}
