 useEffect(()=>{if(!token||me?.is_admin)return;let active=true,connectionErrorShown=false;const refresh=async()=>{try{const [p,d,n,m,b,saved]=await Promise.all([request('/posts'),request('/deals'),request('/notifications'),request('/my-posts'),request('/blogs'),request('/saved')]);if(active){connectionErrorShown=false;setPosts(p);setDeals(d);setNotes(n);setMine(m);setBlogs(b);setSavedPosts(saved);}}catch(e:any){if(active&&!connectionErrorShown){connectionErrorShown=true;Alert.alert('Connection',e.message);}}};const timer=setInterval(()=>{void refresh();},10000);return()=>{active=false;clearInterval(timer);};},[token,me?.is_admin]);
 useEffect(()=>{if(!trackingEnabled||tab!=='Detail'||selected?.type!=='deal'||selected.kind!=='delivery'||selected.status!=='In progress'||Number(selected.worker_id)!==Number(me?.id))return;let active=true,subscription:Location.LocationSubscription|null=null,errorShown=false;Location.watchPositionAsync({accuracy:Location.Accuracy.Balanced,timeInterval:5000,distanceInterval:10},position=>{void request(`/deals/${selected.id}/tracking`,'POST',{latitude:position.coords.latitude,longitude:position.coords.longitude}).then(()=>{if(active)setLiveLocation({sharing:true,latitude:position.coords.latitude,longitude:position.coords.longitude,updated_at:new Date().toISOString()});}).catch((error:any)=>{if(active&&!errorShown){errorShown=true;Alert.alert(t('Live tracking'),error.message);}});}).then(watcher=>{if(active)subscription=watcher;else watcher.remove();}).catch((error:any)=>{if(active)Alert.alert(t('Live tracking'),error.message);});return()=>{active=false;subscription?.remove();setTrackingEnabled(false);void request(`/deals/${selected.id}/tracking`,'DELETE').catch((error:any)=>Alert.alert(t('Live tracking'),error.message));};},[trackingEnabled,tab,selected?.id,selected?.type,selected?.kind,selected?.status,selected?.worker_id,me?.id,token]);
