 async function action(fn:()=>Promise<any>,done?:()=>void){setBusy(true);try{const result=await fn();if(result?.message)Alert.alert('CampusLoop',result.message);done?.();}catch(e:any){Alert.alert('Error',e.message)}finally{setBusy(false)}}
 async function auth(){const email=String(form.email||'').trim();if(!/^[a-z0-9._%+-]+@kongu\.edu$/i.test(email)){Alert.alert(t('Kongu email required'),t('Use your @kongu.edu email address.'));return;}await action(async()=>{if(authMode==='register'){await request('/register','POST',{name:form.name,email,collegeId:form.collegeId,password:form.password,department:form.department||'',year:form.year||''},'');setAuthMode('login');return {message:'Account created. Sign in now.'};}const u=await request('/login','POST',{email,password:form.password},'');await AsyncStorage.setItem('campusloop_token',u.token);setToken(u.token);setMe(u);setTab(u.is_admin?'Admin':'Home');await loadProfileLanguage(Number(u.id));await loadTheme(Number(u.id));setForm({});if(!u.is_admin){await load(u.token);await loadConnections(u.token);}});}
 async function saveProfile(){await action(async()=>{const updated=await request('/profile','POST',{bio:profileBio});await AsyncStorage.setItem('campusloop_language_'+me!.id,profileLanguage);setMe(updated);setEditingProfile(false);return {message:'Profile updated'};});}
 function addAttachments(files:LocalAttachment[]){const remaining=5-localAttachments.length;if(remaining<=0){Alert.alert(t('Attachment limit'),'A listing can have up to 5 files.');return;}const chosen=files.slice(0,remaining);const oversized=chosen.filter(file=>file.size!==undefined&&file.size>10*1024*1024);if(oversized.length){Alert.alert(t('File too large'),'Each file must be 10 MB or smaller.');return;}setLocalAttachments(current=>[...current,...chosen]);}
 async function chooseImages(){const permission=await ImagePicker.requestMediaLibraryPermissionsAsync();if(!permission.granted){Alert.alert(t('Permission required'),t('Allow photo access to add listing pictures.'));return;}const result=await ImagePicker.launchImageLibraryAsync({mediaTypes:['images'],allowsMultipleSelection:true,selectionLimit:Math.max(1,5-localAttachments.length),quality:0.85});if(result.canceled)return;addAttachments(result.assets.map((asset,index)=>({uri:asset.uri,name:asset.fileName||`campus-image-${Date.now()}-${index}.jpg`,mimeType:asset.mimeType||'image/jpeg',size:asset.fileSize})));}
 async function chooseDocuments(){const result=await DocumentPicker.getDocumentAsync({type:'*/*',multiple:true,copyToCacheDirectory:true});if(result.canceled)return;addAttachments(result.assets.map(asset=>({uri:asset.uri,name:asset.name,mimeType:asset.mimeType||'application/octet-stream',size:asset.size})));}
 async function uploadAttachment(postId:number,file:LocalAttachment){const response=await uploadAsync(`${API_BASE_URL}/api/posts/${postId}/attachments`,file.uri,{uploadType:FileSystemUploadType.MULTIPART,fieldName:"file",mimeType:file.mimeType,headers:{Authorization:`Bearer ${token}`}});let body:Item={};try{body=JSON.parse(response.body);}catch{}if(response.status<200||response.status>=300)throw Error(body.error||body.message||`Upload failed for ${file.name}`);}
 async function publishListing(){await action(async()=>{const payload={...form,kind:form.kind||"market",category:form.category||"Other",price:Number(form.isFree?0:form.price),quantity:Number(form.quantity??1)};if(editingPostId!==null){const result=await request(`/posts/${editingPostId}`,'PUT',payload);setEditingPostId(null);setLocalAttachments([]);await load();setTab('Activity');return result;}const post=await request("/posts","POST",payload);const failed:LocalAttachment[]=[],failures:string[]=[];for(const file of localAttachments){try{await uploadAttachment(Number(post.id),file);}catch(error){failed.push(file);failures.push(`${file.name}: ${error instanceof Error?error.message:"Upload failed"}`);}}setLocalAttachments(failed);await load();setTab(form.kind==="task"?"Tasks":"Activity");return {message:failed.length?`${post.message}. ${failed.length} attachment(s) did not upload; open your listing and retry: ${failures.join("; ")}`:`${post.message}${localAttachments.length?` (${localAttachments.length} ${t("files attached")})`:""}`};});}
 function editProduct(post:Item){setEditingPostId(Number(post.id));setLocalAttachments([]);setForm({kind:'market',category:post.category||'Other',title:post.title,description:post.description,price:Number(post.price),isFree:Number(post.price)===0,quantity:Number(post.quantity??1),location:post.location});setTab('Create');}
 async function publishBlog(){await action(async()=>{const result=await request('/blogs','POST',{title:form.blogTitle,body:form.blogBody});setForm({});setTab('Blogs');await load();return result;});}
 async function publishLostFound(){await action(async()=>{const result=await request('/lost-found','POST',{kind:form.lostKind,title:form.lostTitle,description:form.lostDescription,location:form.lostLocation});setForm({});setLostFound(await request('/lost-found'));setTab('LostFound');return result;});}
 async function publishAnnouncement(){await action(async()=>{const result=await request('/admin/announcements','POST',{title:form.announcementTitle,body:form.announcementBody});setAnnouncements(await request('/announcements'));setForm({});return result;});}
 async function resolveLostFoundItem(item:Item){await action(async()=>{const result=await request(`/lost-found/${item.id}/resolve`,'POST');setLostFound(current=>current.map(entry=>entry.id===item.id?{...entry,status:'Resolved'}:entry));return result;});}
 async function startDeliveryTracking(){if(!selected||selected.type!=='deal')return;try{const permission=await Location.requestForegroundPermissionsAsync();if(permission.status!=='granted'){Alert.alert(t('Location permission required'),t('Allow foreground location access to share your position during this active delivery.'));return;}const position=await Location.getCurrentPositionAsync({accuracy:Location.Accuracy.Balanced});await request(`/deals/${selected.id}/tracking`,'POST',{latitude:position.coords.latitude,longitude:position.coords.longitude});setLiveLocation({sharing:true,latitude:position.coords.latitude,longitude:position.coords.longitude,updated_at:new Date().toISOString()});setTrackingEnabled(true);}catch(error:any){Alert.alert(t('Live tracking'),error.message);}}
 async function stopDeliveryTracking(){if(!selected||selected.type!=='deal')return;await action(async()=>{const result=await request(`/deals/${selected.id}/tracking`,'DELETE');setTrackingEnabled(false);setLiveLocation(null);return result;});}
 async function toggleSaved(post:Item){await action(async()=>{const isSaved=savedPosts.some(item=>Number(item.id)===Number(post.id));const result=await request(`/posts/${post.id}/save`,isSaved?'DELETE':'POST');setSavedPosts(current=>isSaved?current.filter(item=>Number(item.id)!==Number(post.id)):[post,...current]);return result;});}
 async function openPost(post:Item){setSelected({type:'post',...post});setAttachments([]);setSellerReviews({average:0,count:0,reviews:[]});setProductReviews({average:0,count:0,reviews:[]});setTab('Detail');try{const [files,ratings,products]=await Promise.all([request(`/posts/${post.id}/attachments`),request(`/users/${post.user_id}/reviews`),post.kind==='market'?request(`/posts/${post.id}/reviews`):Promise.resolve({average:0,count:0,reviews:[]})]);setAttachments(files);setSellerReviews(ratings);setProductReviews(products);}catch(e:any){Alert.alert(t('Connection'),e.message);}}
 async function openDeal(deal:Item){setSelected({type:'deal',...deal});setForm({});setTab('Detail');try{const current=await request(`/deals/${deal.id}`);const [messages,disputes,products]=await Promise.all([request('/deals/'+deal.id+'/messages'),request('/deals/'+deal.id+'/disputes'),current.kind==='market'?request(`/posts/${current.post_id}/reviews`):Promise.resolve({average:0,count:0,reviews:[]})]);setSelected({type:'deal',...current});setChat(messages);setDealDisputes(disputes);setProductReviews(products);}catch(e:any){Alert.alert(t('Connection'),e.message);}}
 async function submitSafetyReport(){if(!selected)return;await action(async()=>{const result=await request('/safety-reports','POST',{postId:selected.type==='post'?selected.id:null,userId:selected.type==='post'?selected.user_id:null,category:form.reportCategory,details:form.reason});setForm({});setTab('Detail');return result;});}
 async function submitDispute(){if(!selected)return;await action(async()=>{const result=await request(`/deals/${selected.id}/disputes`,'POST',{details:form.disputeDetails});setDealDisputes(await request(`/deals/${selected.id}/disputes`));setSelected({...selected,status:'Disputed'});setForm({});await load();return result;});}
 async function submitReview(){if(!selected||!me)return;if(!Number.isInteger(Number(form.rating))||Number(form.rating)<1||Number(form.rating)>5){Alert.alert(t('Rating required'),t('Choose a 1–5 star rating.'));return;}await action(async()=>{const result=await request(`/deals/${selected.id}/reviews`,'POST',{rating:Number(form.rating),body:form.review});setProfileReviews(await request(`/users/${me.id}/reviews`));setSelected({...selected,reviewed_by_me:true});setForm({});return result;});}
 async function submitProductReview(){if(!selected)return;if(!Number.isInteger(Number(form.productRating))||Number(form.productRating)<1||Number(form.productRating)>5){Alert.alert(t('Rating required'),t('Choose a 1–5 star rating.'));return;}if(!String(form.productReview||'').trim()){Alert.alert(t('Review required'),t('Write a review of the product before submitting.'));return;}await action(async()=>{const result=await request(`/deals/${selected.id}/product-review`,'POST',{rating:Number(form.productRating),body:String(form.productReview).trim()});setProductReviews(await request(`/posts/${selected.post_id}/reviews`));setSelected({...selected,product_reviewed_by_me:true});setForm({});return result;});}
 async function submitSupportTicket(){await action(async()=>{const result=await request('/support-tickets','POST',{subject:form.supportSubject,details:form.supportDetails});setForm({});await loadSupportTickets();return result;});}
 async function resolveSafetyReport(id:number){await action(async()=>{const result=await request(`/admin/safety-reports/${id}/resolve`,'POST');await loadAdminData();return result;});}
 async function resolveReport(id:number){await action(async()=>{const result=await request(`/admin/reports/${id}/resolve`,'POST');await loadAdminData();return result;});}
 async function resolveTicket(id:number){await action(async()=>{const result=await request(`/admin/support-tickets/${id}/resolve`,'POST');await loadAdminData();return result;});}
 async function resolveDispute(id:number){await action(async()=>{const result=await request(`/admin/disputes/${id}/resolve`,'POST',{resolution:form[`resolution_${id}`],decision:form[`decision_${id}`]});await loadAdminData();await load();return result;});}
 async function retryAttachments(postId:number){await action(async()=>{const failed:LocalAttachment[]=[],failures:string[]=[];for(const file of localAttachments){try{await uploadAttachment(postId,file);}catch(error){failed.push(file);failures.push(`${file.name}: ${error instanceof Error?error.message:'Upload failed'}`);}}setLocalAttachments(failed);setAttachments(await request(`/posts/${postId}/attachments`));return {message:failed.length?`${failed.length} attachment(s) still failed: ${failures.join('; ')}`:'Attachments uploaded'};});}
 async function logout(){await action(async()=>{await request('/logout','POST');await AsyncStorage.removeItem('campusloop_token');setToken('');setMe(null);setTab('Home');setSelected(null);setChatPerson(null);setConnections([]);setTrackingEnabled(false);setLiveLocation(null);setIsDark(false);});}
 const btn=(label:string,onPress:()=>void,outline=false)=><TouchableOpacity disabled={busy} style={[styles.button,outline&&styles.outline]} onPress={onPress}><Text style={[styles.buttonText,outline&&{color:C.blue}]}>{t(label)}</Text></TouchableOpacity>;
 const starRating=(key:string)=><View accessibilityLabel={t('Choose a 1–5 star rating.')} style={{flexDirection:'row',alignItems:'center',marginVertical:8}}>{[1,2,3,4,5].map(star=><TouchableOpacity key={star} onPress={()=>change(key,String(star))} accessibilityRole="button" accessibilityLabel={`${star} ${t('out of 5 stars')}`} accessibilityState={{selected:Number(form[key])===star}} style={{padding:5}}><Ionicons name={Number(form[key])>=star?'star':'star-outline'} size={32} color={Number(form[key])>=star?'#F5B544':C.muted}/></TouchableOpacity>)}</View>;
 const field=(key:string,placeholder:string,multiline=false,secure=false)=><TextInput placeholder={t(placeholder)} placeholderTextColor={C.muted} value={String(form[key]||'')} onChangeText={v=>change(key,v)} multiline={multiline} secureTextEntry={secure} keyboardType={key.toLowerCase().includes('price')||(key.toLowerCase().includes('quantity')||key.toLowerCase()==='rating')?'numeric':'default'} autoCapitalize={key==='email'?'none':'sentences'} style={[styles.input,multiline&&{height:90,textAlignVertical:'top'}]}/>;
 const heading=(name:string,sub:string)=><View style={{marginBottom:16}}><Text style={styles.heading}>{t(name)}</Text><Text style={styles.sub}>{t(sub)}</Text></View>;
 const featureTile=(title:string,subtitle:string,icon:any,onPress:()=>void)=><TouchableOpacity key={title} activeOpacity={0.82} style={{width:'48%',minHeight:116,backgroundColor:C.surface,borderRadius:22,borderWidth:1,borderColor:C.line,padding:15,marginBottom:12,elevation:1,shadowColor:'#243366',shadowOpacity:0.04,shadowRadius:8,shadowOffset:{width:0,height:3}}} onPress={onPress}><View style={{width:38,height:38,borderRadius:14,backgroundColor:C.pale,alignItems:'center',justifyContent:'center',marginBottom:10}}><Ionicons name={icon} size={20} color={C.blue}/></View><Text style={{fontSize:14,fontWeight:'800',color:C.navy}}>{t(title)}</Text><Text style={{fontSize:11,color:C.muted,marginTop:4,lineHeight:16}}>{t(subtitle)}</Text></TouchableOpacity>;
 const campusMapIllustration=<View style={{width:'100%',aspectRatio:1,backgroundColor:isDark?'#1B493F':'#DDF3E7',overflow:'hidden',position:'relative'}}>
  {CAMPUS_MAP_ROADS.flatMap((road,roadIndex)=>road.points.slice(1).map((point,segmentIndex)=>{
   const start=road.points[segmentIndex];
   const dx=point[0]-start[0],dy=point[1]-start[1],length=Math.hypot(dx,dy),angle=`${Math.atan2(dy,dx)*180/Math.PI}deg`;
   const casingHeight=road.kind==='main'?18:road.kind==='path'?7:12;
   const surfaceHeight=road.kind==='main'?11:road.kind==='path'?3:7;
   return <React.Fragment key={`${roadIndex}-${segmentIndex}`}>
    <View pointerEvents="none" style={{position:'absolute',left:`${(start[0]+point[0])/2}%`,top:`${(start[1]+point[1])/2}%`,width:`${length}%`,height:casingHeight,marginLeft:`${-length/2}%`,marginTop:-casingHeight/2,borderRadius:casingHeight/2,backgroundColor:isDark?'#536071':'#F8F9FB',transform:[{rotate:angle}]}}/>
    <View pointerEvents="none" style={{position:'absolute',left:`${(start[0]+point[0])/2}%`,top:`${(start[1]+point[1])/2}%`,width:`${length}%`,height:surfaceHeight,marginLeft:`${-length/2}%`,marginTop:-surfaceHeight/2,borderRadius:surfaceHeight/2,backgroundColor:isDark?'#84909E':'#D5DBE4',transform:[{rotate:angle}]}}/>
   </React.Fragment>;
  }))}
  {CAMPUS_MAP_PLACES.map(place=>{
   const x=((place.lon-CAMPUS_MAP_BOUNDS.west)/(CAMPUS_MAP_BOUNDS.east-CAMPUS_MAP_BOUNDS.west))*100;
   const y=((CAMPUS_MAP_BOUNDS.north-place.lat)/(CAMPUS_MAP_BOUNDS.north-CAMPUS_MAP_BOUNDS.south))*100;
   const open=()=>openCampusLocation(place.location,{lat:place.lat,lon:place.lon});
   const PIN=13,GAP=2,LABEL_W=72,LABEL_H=26;const labelPosition:any=place.side==='above'?{left:`${x}%`,bottom:`${100-y}%`,marginLeft:-LABEL_W/2,marginBottom:PIN+GAP}:place.side==='left'?{right:`${100-x}%`,top:`${y}%`,marginRight:PIN+GAP,marginTop:-LABEL_H/2}:place.side==='right'?{left:`${x}%`,top:`${y}%`,marginLeft:PIN+GAP,marginTop:-LABEL_H/2}:{left:`${x}%`,top:`${y}%`,marginLeft:-LABEL_W/2,marginTop:PIN+GAP};
   return <React.Fragment key={place.label}>
    <TouchableOpacity onPress={open} accessibilityRole="button" accessibilityLabel={`${t(place.label)}. ${t('Open in Google Maps?')}`} hitSlop={{top:4,bottom:4,left:4,right:4}} style={{position:'absolute',left:`${x}%`,top:`${y}%`,width:26,height:26,marginLeft:-13,marginTop:-13,alignItems:'center',justifyContent:'center',zIndex:3}}>
     <View style={{width:26,height:26,borderRadius:13,backgroundColor:'#7546C8',alignItems:'center',justifyContent:'center',borderWidth:2,borderColor:'white',elevation:4,shadowColor:'#33204F',shadowOpacity:0.24,shadowRadius:4,shadowOffset:{width:0,height:2}}}><Ionicons name={place.icon as any} size={13} color="white"/></View>
    </TouchableOpacity>
    <TouchableOpacity onPress={open} accessibilityRole="button" accessibilityLabel={`${t(place.label)}. ${t('Open in Google Maps?')}`} style={{position:'absolute',...labelPosition,width:LABEL_W,minHeight:LABEL_H,paddingHorizontal:4,paddingVertical:3,borderRadius:8,backgroundColor:'white',alignItems:'center',justifyContent:'center',elevation:2,shadowColor:'#26334A',shadowOpacity:0.14,shadowRadius:3,shadowOffset:{width:0,height:1},zIndex:2}}>
     <Text numberOfLines={2} adjustsFontSizeToFit style={{fontSize:8,fontWeight:'800',color:'#253049',textAlign:'center'}}>{t(place.label)}</Text>
    </TouchableOpacity>
   </React.Fragment>;
  })}
  <View pointerEvents="none" style={{position:'absolute',top:7,right:7,width:29,height:29,borderRadius:15,backgroundColor:'white',alignItems:'center',justifyContent:'center',zIndex:3}}><Ionicons name="navigate" size={14} color="#7546C8"/></View>
 </View>;
 const locationPicker=(key:string,label:string)=><View><Text style={styles.label}>{t(label)}</Text><TouchableOpacity style={{backgroundColor:C.surface,borderColor:C.line,borderWidth:1,borderRadius:12,padding:14,marginBottom:locationMenu===key?0:12,flexDirection:'row',justifyContent:'space-between',alignItems:'center'}} accessibilityRole="button" accessibilityLabel={t(label)} accessibilityState={{expanded:locationMenu===key}} onPress={()=>setLocationMenu(locationMenu===key?'':key)}><Text style={{fontSize:15,color:form[key]?C.navy:C.muted}}>{form[key]?t(String(form[key])):t('Select a campus location')}</Text><Ionicons name={locationMenu===key?'chevron-up':'chevron-down'} size={20} color={C.blue}/></TouchableOpacity>{locationMenu===key&&<View style={{backgroundColor:C.surface,borderColor:C.line,borderWidth:1,borderRadius:12,marginBottom:12,maxHeight:260,overflow:'hidden'}}><ScrollView nestedScrollEnabled keyboardShouldPersistTaps="handled">{CAMPUS_LOCATIONS.map(location=><TouchableOpacity key={`${key}-${location}`} style={{paddingHorizontal:14,paddingVertical:12,borderBottomColor:C.line,borderBottomWidth:1,flexDirection:'row',justifyContent:'space-between',alignItems:'center',backgroundColor:form[key]===location?C.pale:C.surface}} onPress={()=>{change(key,location);setLocationMenu('');}}><Text style={{fontSize:15,color:form[key]===location?C.blue:C.navy,fontWeight:form[key]===location?'800':'400'}}>{t(location)}</Text>{form[key]===location&&<Ionicons name="checkmark" size={19} color={C.blue}/>}</TouchableOpacity>)}</ScrollView></View>}</View>;
 const card=(p:Item)=><View key={p.id}><TouchableOpacity style={styles.card} onPress={()=>openPost(p)}><Text style={styles.tag}>{t(p.kind==='market'?(Number(p.price)===0?'Free item':'FOR SALE'):p.kind==='task'?'TASK BOARD':'PICK & DROP')}{p.kind==='market'&&p.category?' · '+t(p.category).toUpperCase():''}</Text><View style={{marginTop:6,alignItems:'flex-start'}}><Text style={styles.price}>{p.kind==='market'&&Number(p.price)===0?t('Free'):`INR ${p.price}`}</Text>{p.kind==='market'&&<Text style={{fontSize:12,color:C.muted,marginTop:2}}>{t('Available')}: {p.quantity??1}</Text>}</View><Text style={styles.cardTitle}>{p.title}</Text>{p.kind==='market'&&Number(p.product_review_count)>0&&<Text style={styles.small}>★ {Number(p.product_rating).toFixed(1)} · {p.product_review_count} {t('product ratings')}</Text>}<Text style={styles.sub} numberOfLines={2}>{p.description}</Text>{p.kind==='delivery'?<><Text style={styles.small}>{t('Pickup:')} {p.location}</Text><Text style={styles.small}>{t('Drop-off:')} {p.destination||t('Not specified')}</Text></>:<Text style={styles.small}>📍 {p.location}</Text>}<Text style={styles.small}>{t(p.status)}</Text></TouchableOpacity>{p.kind==='market'&&Number(p.user_id)===Number(me?.id)&&['Open','Completed'].includes(p.status)&&btn('Edit product',()=>editProduct(p),true)}</View>;
 if(!me)return <SafeAreaView style={styles.safe}><ScrollView contentContainerStyle={styles.auth}><View style={styles.logo}><Ionicons name="infinite" size={34} color="white"/></View><Text style={styles.brand}>CampusLoop</Text><Text style={styles.sub}>Your campus. One connected community.</Text><View style={styles.authCard}>{heading(authMode==='login'?'Welcome back':'Join your campus',authMode==='login'?'Sign in to continue':'Create your student account')}{authMode==='register'&&<>{field('name','Full name')}{field('collegeId','College ID')}</>}{field('email','College email (@kongu.edu)')}{authMode==='register'&&<>{field('department','Department')}{field('year','Year of study')}</>}{field('password','Password (minimum 8 characters)',false,true)}{btn(busy?'Please wait...':authMode==='login'?'Sign in':'Create account',auth)}<TouchableOpacity onPress={()=>{setAuthMode(authMode==='login'?'register':'login');setForm({})}}><Text style={styles.link}>{authMode==='login'?'New here? Create an account':'Already registered? Sign in'}</Text></TouchableOpacity></View><Text style={styles.small}>Demo: campus ID is self-declared, not verified.</Text></ScrollView></SafeAreaView>;
 const tabButton=(name:string,icon:any)=><TouchableOpacity style={styles.navItem} activeOpacity={0.75} accessibilityRole="button" accessibilityState={{selected:tab===name}} onPress={()=>{setTab(name);setSelected(null);setForm({});if(name==='Home'||name==='Activity'||name==='Profile'||name==='Tasks')load();if(name==='Connect')loadConnections();if(name==='Profile'&&me){setProfileBio(String(me.bio||''));request(`/users/${me.id}/reviews`).then(setProfileReviews).catch((e:any)=>Alert.alert('Reviews',e.message));}if(name==='Admin')loadAdminData();if(name==='Settings')loadSupportTickets();}}><View style={[styles.navIcon,tab===name&&{backgroundColor:C.pale}]}><Ionicons name={icon} size={21} color={tab===name?C.blue:C.muted}/></View><Text style={[styles.navText,tab===name&&{color:C.blue}]}>{t(name)}</Text></TouchableOpacity>;
 const dealCard=(d:Item)=><TouchableOpacity key={d.id} style={styles.card} onPress={()=>void openDeal(d)}><View style={styles.between}><Text style={styles.tag}>{t(d.kind==='delivery'?'PICK & DROP ORDER':d.kind==='task'?'TASK VOLUNTEER OFFER':'MARKETPLACE ORDER')}</Text><Text style={styles.small}>{t(d.status)}</Text></View><Text style={styles.cardTitle}>{d.title}</Text><Text style={styles.sub}>#{d.id} | {t('Quantity')}: {d.quantity} | INR {d.price} each | {t('Total')}: INR {d.total_price}</Text><Text style={styles.small}>{d.owner_name} ↔ {d.worker_name}</Text>{d.kind==='delivery'&&<><Text style={styles.small}>{t('Pickup:')} {d.location}</Text><Text style={styles.small}>{t('Drop-off:')} {d.destination}</Text></>}</TouchableOpacity>;
 const soldListings=mine.filter(item=>item.kind==='market'&&(Number(item.quantity||0)<=0||item.status==='Completed'));
 const unsoldListings=mine.filter(item=>item.kind==='market'&&Number(item.quantity||0)>0&&item.status!=='Completed');
